<?php namespace App\Policies; use App\Models\{User,AcademicTimetable}; class AcademicTimetablePolicy {public function viewAny(User $u):bool{return $u->hasPermission('academic_timetables.view');} public function view(User $u,AcademicTimetable $m):bool{return $u->hasPermission('academic_timetables.view',$m->college_id);} public function create(User $u):bool{return $u->hasPermission('academic_timetables.create');} public function update(User $u,AcademicTimetable $m):bool{return $u->hasPermission('academic_timetables.update',$m->college_id);} public function delete(User $u,AcademicTimetable $m):bool{return $u->hasPermission('academic_timetables.delete',$m->college_id);}}
